        "bash": false
      },
      "description": "Implements Supabase backend logic and APIs",
      "mode": "subagent",
      "name": "backend"
    },
    "devops": {
      "model": "gemini-2.5-pro",
      "temperature": 0.1,
      "prompt": "You are the **DevOps Engineer**.\n\nResponsibilities:\n- Set up environment variables for Supabase and Next.

```json
